import type { NextApiRequest, NextApiResponse } from 'next';
import fs from 'fs';

export const config = {
  api: {
    bodyParser: false,
  },
};

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }
  const { IncomingForm } = await import('formidable');
  const form = new IncomingForm();

  // Wrap form.parse in a Promise
  const data = await new Promise<{ fields: any; files: any }>((resolve, reject) => {
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  }).catch((err) => {
    res.status(500).json({ error: 'Error parsing form data', details: String(err) });
    return null;
  });

  if (!data) return;

  let pdfFile = data.files.pdf;
  if (Array.isArray(pdfFile)) pdfFile = pdfFile[0];
  if (!pdfFile || !('filepath' in pdfFile)) {
    return res.status(400).json({ error: 'No PDF file uploaded.' });
  }
  try {
    // Dynamically import FormData and node-fetch
    const FormData = (await import('form-data')).default;
    const fetch = (await import('node-fetch')).default;
    // Forward the PDF file to the FastAPI backend
    const formData = new FormData();
    formData.append('file', fs.createReadStream(pdfFile.filepath), pdfFile.originalFilename || 'upload.pdf');
    const response = await fetch('http://localhost:8000/index-pdf/', {
      method: 'POST',
      body: formData,
      headers: formData.getHeaders(),
    });
    fs.unlinkSync(pdfFile.filepath);
    if (!response.ok) {
      const error = await response.json();
      return res.status(response.status).json({ error: 'Failed to index PDF', details: error });
    }
    const result = await response.json();
    return res.status(200).json(result);
  } catch (error) {
    return res.status(500).json({ error: 'Failed to process PDF.', details: String(error) });
  }
} 